import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PINS = [2, 3, 4]
INTERVAL = 60

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            dev = OutputDevice(pin)
            dev.on()
            devices.append(dev)
            print(f"GPIO {pin} set HIGH", flush=True)

        while _running:
            time.sleep(INTERVAL)
            if not _running:
                break
            for dev in devices:
                try:
                    dev.on()
                    print(f"GPIO {dev.pin.number} set HIGH", flush=True)
                except DeviceClosed:
                    print(f"Error: GPIO {dev.pin.number} closed during cycle", file=sys.stderr, flush=True)
                    _running = False
                    break

    except GPIOZeroError as exc:
        print(f"GPIO error: {exc}", file=sys.stderr, flush=True)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr, flush=True)
        sys.exit(1)
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.", flush=True)


if __name__ == "__main__":
    main()

import signal
import sys
import time

from luma.core.interface.serial import i2c
from luma.core.render import canvas
from luma.oled.device import ssd1306

# --- Configuration -----------------------------------------------------------
I2C_BUS = 1
I2C_ADDR = 0x3C          # SSD1306 default I2C address (0x3C / 0x3D)
UPDATE_INTERVAL_S = 2.0

# --- Globals for cleanup -----------------------------------------------------
_device = None
_running = True


def _cleanup():
    """Release the OLED display and I2C bus."""
    global _device
    if _device is not None:
        try:
            _device.cleanup()
        except Exception:
            pass
        _device = None


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _read_sensor_data():
    """
    Simulate reading sensor data.
    Replace with real sensor reads (e.g., adafruit_dht.DHT11, BME280, etc.).
    Returns a dict of values, or None if the reading is invalid.
    """
    # Example: a real sensor would return a dict like:
    #   {'temperature': 25.5, 'humidity': 50.2, 'pressure': 1013.2}
    # Here we return a simulated value for demonstration.
    return {'temperature': 25.5, 'humidity': 50.2, 'pressure': 1013.2}


def _validate_reading(reading):
    """Validate that the reading contains all expected keys and values are finite."""
    if reading is None:
        return False
    for key in ('temperature', 'humidity', 'pressure'):
        if key not in reading:
            return False
        if not isinstance(reading[key], (int, float)) or not isinstance(reading[key], float):
            return False
        if not isfinite(reading[key]):
            return False
    return True


def main():
    global _device

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # --- Initialize I2C bus --------------------------------------------------
    try:
        serial = i2c(port=I2C_BUS, address=I2C_ADDR)
    except Exception as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS} at 0x{I2C_ADDR:02X}: {exc}", file=sys.stderr)
        sys.exit(1)

    # --- Initialize SSD1306 OLED --------------------------------------------
    try:
        _device = ssd1306(serial)
    except Exception as exc:
        print(f"Error: SSD1306 not detected on I2C bus {I2C_BUS} at 0x{I2C_ADDR:02X}: {exc}",
              file=sys.stderr)
        _cleanup()
        sys.exit(1)

    # --- Main loop -----------------------------------------------------------
    try:
        while _running:
            reading = _read_sensor_data()

            if not _validate_reading(reading):
                print("Warning: invalid reading, skipping display update.", file=sys.stderr)
            else:
                try:
                    with canvas(_device) as draw:
                        draw.text((0, 0), f"Temp: {reading['temperature']:.1f} C", fill="white")
                        draw.text((0, 12), f"Hum:  {reading['humidity']:.1f} %", fill="white")
                        draw.text((0, 24), f"Pres: {reading['pressure']:.1f} hPa", fill="white")
                except Exception as exc:
                    print(f"Warning: display update failed: {exc}", file=sys.stderr)

            # Sleep in small increments so signals are caught promptly
            elapsed = 0.0
            while _running and elapsed < UPDATE_INTERVAL_S:
                time.sleep(0.1)
                elapsed += 0.1

    finally:
        _cleanup()


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

PINS = [1, 2, 3, 4]
INTERVAL = 0.1

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_and_report(pwm_devices):
    """Read each PWM device and report its value. Returns True if all readings are valid."""
    all_valid = True
    for pin, dev in zip(PINS, pwm_devices):
        try:
            value = dev.value
            print(f"GPIO {pin}: {value:.3f}")
        except GPIOZeroError as exc:
            print(f"GPIO {pin}: read error - {exc}", file=sys.stderr)
            all_valid = False
    return all_valid


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    pwm_devices = []
    try:
        for pin in PINS:
            dev = PWMOutputDevice(pin)
            pwm_devices.append(dev)
        print(f"PWM output devices initialized on GPIO {PINS} (BCM).")

        while _running:
            if not read_and_report(pwm_devices):
                print("Warning: one or more readings failed; continuing.", file=sys.stderr)
            time.sleep(INTERVAL)

    except GPIOZeroError as exc:
        print(f"GPIO initialization error: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        for dev in pwm_devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO resources released.")


if __name__ == "__main__":
    main()

