import signal
import sys
from gpiozero import PWMOutputDevice

# BCM pin numbers that will be driven as PWM outputs
PWM_PINS = [9, 10, 11, 12, 13]

# Global list so the signal handler can close them cleanly
_pwm_devices = []


def _cleanup(signum=None, frame=None):
    """Close every PWM device and exit."""
    for dev in _pwm_devices:
        try:
            dev.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main():
    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    try:
        for pin in PWM_PINS:
            # gpiozero PWMOutputDevice uses 0.0–1.0 for duty cycle
            dev = PWMOutputDevice(pin, initial_value=0.5, frequency=1000)
            _pwm_devices.append(dev)

        # Drive the PWM outputs and report their final states
        for dev in _pwm_devices:
            # Validate the written value
            if not 0.0 <= dev.value <= 1.0:
                raise RuntimeError(f"PWM value {dev.value} out of range")
            print(f"PWM on GPIO {dev.pin.number} set to {dev.value:.3f}")

    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

