from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PIN = 17
INTERVAL = 0.1

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        led = OutputDevice(PIN)
    except GPIOZeroError as exc:
        print(f"Error: cannot open GPIO {PIN}: {exc}", file=sys.stderr)
        return 1
    except Exception as exc:
        print(f"Unexpected error opening GPIO {PIN}: {exc}", file=sys.stderr)
        return 1

    try:
        while _running:
            try:
                led.on()
            except DeviceClosed:
                print("Error: device was closed unexpectedly.", file=sys.stderr)
                return 1
            print(f"GPIO {PIN} set to HIGH")

            time.sleep(INTERVAL)
            if not _running:
                break

            try:
                led.off()
            except DeviceClosed:
                print("Error: device was closed unexpectedly.", file=sys.stderr)
                return 1
            print(f"GPIO {PIN} set to LOW")

            time.sleep(INTERVAL)

    finally:
        try:
            led.close()
        except Exception:
            pass

    return 0


if __name__ == "__main__":
    sys.exit(main())

import signal
import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

ECHO_PIN = 22
TRIGGER_PIN = 17
MAX_DISTANCE_M = 3.0
TIMEOUT_S = 1.0
CYCLES = 5
INTERVAL_S = 50

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = DistanceSensor(
            echo=ECHO_PIN,
            trigger=TRIGGER_PIN,
            max_distance=MAX_DISTANCE_M,
        )
    except GPIOZeroError as exc:
        print(f"Failed to initialize sensor: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for cycle in range(1, CYCLES + 1):
            if not _running:
                break

            try:
                distance = sensor.distance
            except DeviceClosed:
                print("Sensor device closed unexpectedly.", file=sys.stderr)
                break
            except Exception as exc:
                print(f"Error reading distance: {exc}", file=sys.stderr)
                break

            if distance is None:
                print(f"Cycle {cycle}: no echo received (timeout).")
            else:
                print(f"Cycle {cycle}: distance = {distance:.3f} m")

            if cycle < CYCLES and _running:
                time.sleep(INTERVAL_S)

    finally:
        try:
            sensor.close()
        except Exception:
            pass

    print("Program finished.")

if __name__ == "__main__":
    main()

