import signal
import sys
import time
from picamera2 import Picamera2

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def capture_image(camera, filename):
    """Capture an image from the camera and save it to a file.

    Returns True on success, False on failure.
    """
    try:
        camera.capture_file(filename)
        return True
    except Exception as e:
        print(f"Error capturing image: {e}", file=sys.stderr)
        return False

def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    camera = None
    try:
        camera = Picamera2()
        camera.start()
        time.sleep(2)  # Allow camera to warm up

        if not _running:
            return

        if not capture_image(camera, "image.jpg"):
            print("Failed to capture image.", file=sys.stderr)
            return

        print("Image captured successfully!")

    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
    finally:
        if camera is not None:
            try:
                camera.stop()
            except Exception:
                pass

if __name__ == "__main__":
    main()

