import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PINS = [17, 18, 27]
INTERVAL = 60

_running = True
_devices = []


def _handle_signal(signum, frame):
    global _running
    _running = False


def apply_state(device, pin):
    device.on()
    print(f"Pin {pin} set to HIGH")


def main():
    global _devices

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    for pin in PINS:
        try:
            dev = OutputDevice(pin)
            _devices.append(dev)
        except GPIOZeroError as exc:
            print(f"Error initializing GPIO {pin}: {exc}", file=sys.stderr)
            for d in _devices:
                d.close()
            sys.exit(1)

    try:
        while _running:
            for dev, pin in zip(_devices, PINS):
                apply_state(dev, pin)
            time.sleep(INTERVAL)
    except DeviceClosed:
        print("Device was closed unexpectedly.", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        for dev in _devices:
            try:
                dev.close()
            except Exception:
