import signal
import sys
import time

from gpiozero import DistanceSensor

# HC-SR04 ultrasonic distance sensor on a Raspberry Pi
# BCM 17 = echo, BCM 18 = trigger
# BCM 22 = echo, BCM 23 = trigger
SENSOR_PINS = {
    "echo_1": 17,
    "trigger_1": 18,
    "echo_2": 22,
    "trigger_2": 23,
}

# gpiozero DistanceSensor uses the Linux kernel's echoc/trigger driver
# which supports the HC-SR04 protocol.  The maximum range is 4.0 m
# (400 cm) and the minimum is 2.0 cm (20 mm).
MAX_RANGE_M = 4.0
MIN_RANGE_M = 2.0

# Graceful shutdown flag
_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensors = {}
    try:
        for name, pin in SENSOR_PINS.items():
            sensors[name] = DistanceSensor(
                echo=pin,
                trigger=pin + 1,
                max_distance=MAX_RANGE_M,
                threshold_distance=MIN_RANGE_M,
            )
        print("HC-SR04 sensors initialized (BCM 17/18, 22/23).")

        while _running:
            readings = []
            for name, sensor in sensors.items():
                try:
                    distance = sensor.distance
                    # gpiozero returns 0.0 when no echo is received
                    if distance == 0.0:
                        readings.append(f"{name}: out of range")
                    else:
                        readings.append(f"{name}: {distance:.2f} m")
                except Exception as exc:
                    readings.append(f"{name}: error ({exc})")

            print(" | ".join(readings))
            time.sleep(5)

    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
    finally:
        # gpiozero closes the underlying GPIO pins on close()
        for sensor in sensors.values():
            try:
                sensor.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

