import serial
import time
import sys

# Serial port configuration for Raspberry Pi (UART0 on the 40-pin header)
# Baud rate: 9600 bits per second
# 8 data bits, no parity, 1 stop bit
SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT_SEC = 2
READ_INTERVAL_SEC = 5


def open_serial_port() -> serial.Serial:
    """Open the serial port with error handling."""
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT_SEC,
        )
        print(f"Opened {SERIAL_PORT} @ {BAUD_RATE} baud")
        return ser
    except serial.SerialException as exc:
        print(f"Error opening serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        sys.exit(1)


def read_sensor_data(ser: serial.Serial) -> str | None:
    """
    Read one line from the serial port.
    Returns the stripped string, or None if the port is not open or no data.
    """
    if not ser.is_open:
        print("Serial port is not open.", file=sys.stderr)
        return None

    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Error reading from serial port: {exc}", file=sys.stderr)
        return None

    if not raw:
        # Timeout elapsed with no data
        return None

    return raw.decode('ascii', errors='replace').strip()


def validate_data(data: str) -> bool:
    """
    Basic validation: reject empty strings and strings that do not look like
    a simple numeric reading.
    """
    if not data:
        return False
    try:
        float(data)
    except ValueError:
        return False
    return True


def process_data(data: str) -> None:
    """Print the validated reading to standard output."""
    print(f"Sensor Reading: {data}")


def main() -> None:
    ser = open_serial_port()
    try:
        while True:
            data = read_sensor_data(ser)
            if data is not None:
                if validate_data(data):
                    process_data(data)
                else:
                    print(f"Invalid data received: {data}", file=sys.stderr)
            time.sleep(READ_INTERVAL_SEC)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

PINS = [4, 17, 22, 27]
INTERVAL_S = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_and_drive(device):
    """Read a PWM value from the device and drive it to the pin."""
    try:
        value = device.value
    except GPIOZeroError as exc:
        print(f"[ERROR] Failed to read PWM value: {exc}", file=sys.stderr)
        return False

    if not (0.0 <= value <= 1.0):
        print(f"[WARN] Invalid PWM value {value}; skipping.", file=sys.stderr)
        return False

    print(f"PWM value: {value:.3f}")
    return True


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            dev = PWMOutputDevice(pin)
            dev.value = 0.0
            devices.append(dev)
            print(f"PWM output initialized on GPIO {pin}")

        while _running:
            for dev in devices:
                if not _running:
                    break
                read_and_drive(dev)
            if _running:
                time.sleep(INTERVAL_S)

    except GPIOZeroError as exc:
        print(f"[FATAL] GPIO initialization failed: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
