import sys
import time

PORT = '/dev/serial0'
BAUD = 9600
TIMEOUT_S = 1.0
LOOP_INTERVAL_S = 1.0


def open_serial_port() -> serial.Serial:
    """Open the serial port with error handling."""
    try:
        return serial.Serial(PORT, BAUD, timeout=TIMEOUT_S)
    except serial.SerialException as exc:
        print(f"Error opening serial port {PORT}: {exc}", file=sys.stderr)
        sys.exit(1)


def read_valid_data(ser: serial.Serial) -> str | None:
    """Read one line from the serial port and validate it.

    Returns the stripped string, or None if the read times out, the
    device sends nothing, or the data is invalid.
    """
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None

    if not raw:
        # Timeout: no data received within TIMEOUT_S.
        return None

    try:
        text = raw.decode('ascii', errors='replace').strip()
    except Exception as exc:
        print(f"Decode error: {exc}", file=sys.stderr)
        return None

    if not text:
        return None

    # Basic validity check: reject non-numeric data.
    try:
        float(text)
    except ValueError:
        print(f"Invalid data (not numeric): {text!r}", file=sys.stderr)
        return None

    return text


def main() -> None:
    ser = open_serial_port()
    print(f"Listening on {PORT} @ {BAUD} baud. Press Ctrl+C to stop.")

    try:
        while True:
            data = read_valid_data(ser)
            if data is not None:
                print(f"Received: {data}")
            time.sleep(LOOP_INTERVAL_S)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        try:
            ser.close()
            print("Serial port closed.")
        except Exception as exc:
            print(f"Error closing serial port: {exc}", file=sys.stderr)


