import serial
import sys
import signal

PORT = '/dev/serial0'
BAUD = 9600
TIMEOUT_S = 2.0
READ_INTERVAL_S = 0.1
MAX_READINGS = 10

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def open_serial():
    try:
        return serial.Serial(PORT, BAUD, timeout=TIMEOUT_S)
    except serial.SerialException as exc:
        print(f'Error opening serial port {PORT}: {exc}', file=sys.stderr)
        return None

def read_valid_value(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f'Serial read error: {exc}', file=sys.stderr)
        return None
    if not raw:
        return None
    try:
        text = raw.decode('ascii', errors='replace').strip()
    except Exception as exc:
        print(f'Decode error: {exc}', file=sys.stderr)
        return None
    if not text:
        return None
    try:
        value = float(text)
    except ValueError:
        print(f'Non-numeric data ignored: {text!r}', file=sys.stderr)
        return None
    if not (-100.0 <= value <= 100.0):
        print(f'Value {value} out of range; skipped.', file=sys.stderr)
        return None
    return value

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = open_serial()
    if ser is None:
        sys.exit(1)

    readings_taken = 0
    try:
        while _running and readings_taken < MAX_READINGS:
            value = read_valid_value(ser)
            if value is not None:
                print(f'Received: {value}')
                readings_taken += 1
            if _running and readings_taken < MAX_READINGS:
                ser.reset_input_buffer()
                ser.reset_output_buffer()
                ser.interrupt_callback()
                time.sleep(READ_INTERVAL_S)
    finally:
        try:
            ser.close()
        except Exception:
            pass

    if readings_taken < MAX_READINGS:
        print('Device not responding or disconnected.', file=sys.stderr)
        sys.exit(1)

