    main()

import signal
import sys
import time

import smbus2

I2C_BUS = 1
TSL2561_ADDR = 0x39

REG_CONTROL = 0x00
REG_TIMING = 0x01
REG_DATA0 = 0x0C
REG_DATA1 = 0x0E

CONTROL_POWER_ON = 0x03
TIMING_INTEGRATION_13MS = 0x00

INTEGRATION_TIME_MS = {
    0x00: 13,
    0x01: 101,
    0x02: 402,
}

running = True


def _signal_handler(signum, frame):
    global running
    running = False


def _write_reg(bus, reg, value):
    bus.write_byte_data(TSL2561_ADDR, reg, value)


def _read_reg(bus, reg):
    return bus.read_byte_data(TSL2561_ADDR, reg)


def _read_word(bus, reg):
    data = bus.read_i2c_block_data(TSL2561_ADDR, reg, 2)
    return (data[0] << 8) | data[1]


def _read_lux(bus):
    _write_reg(bus, REG_CONTROL, CONTROL_POWER_ON)
    time.sleep(0.01)
    _write_reg(bus, REG_TIMING, TIMING_INTEGRATION_13MS)
    time.sleep(0.013)

    ch0 = _read_word(bus, REG_DATA0)
    ch1 = _read_word(bus, REG_DATA1)

    if ch0 == 0xFFFF or ch1 == 0xFFFF:
        raise IOError("TSL2561 returned invalid data (0xFFFF).")

    if ch0 == 0x0000 or ch1 == 0x0000:
        raise IOError("TSL2561 returned zero channel data.")

    ratio = ch1 / ch0
    if ratio <= 0.50:
        lux = (0.0304 * ch0) - (0.062 * ch0 * (ratio ** 1.4))
    elif ratio <= 0.61:
        lux = (0.0224 * ch0) - (0.031 * ch1)
    elif ratio <= 0.80:
        lux = (0.0128 * ch0) - (0.0153 * ch1)
    elif ratio <= 1.30:
        lux = (0.00146 * ch0) - (0.00112 * ch1)
    else:
        lux = 0.0

    if lux < 0.0:
        lux = 0.0
    return lux


def main():
    global running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        bus = smbus2.SMBus(I2C_BUS)
    except FileNotFoundError:
        print("Error: I2C bus 1 not found. Enable I2C with 'sudo raspi-config'.", file=sys.stderr)
        sys.exit(1)
    except PermissionError:
        print("Error: Permission denied on I2C bus. Run as root or add user to 'i2c' group.", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"Error: Failed to open I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            _write_reg(bus, REG_CONTROL, CONTROL_POWER_ON)
            time.sleep(0.01)
        except OSError:
            print(f"Error: TSL2561 not found at address 0x{TSL2561_ADDR:02X}.", file=sys.stderr)
            sys.exit(1)

        while running:
            try:
                lux = _read_lux(bus)
                print(f"Lux: {lux:.2f}")
            except OSError as e:
                print(f"Error reading TSL2561: {e}", file=sys.stderr)
            except IOError as e:
                print(f"Error: {e}", file=sys.stderr)

            time.sleep(0.1)
    finally:
        try:
            _write_reg(bus, REG_CONTROL, 0x00)
        except OSError:
            pass
        bus.close()


if __name__ == "__main__":
    main()

