import time
import signal
import sys
import smbus2

# TSL2561 I2C address (ADDR pin low = 0x39, high = 0x49)
TSL2561_ADDR = 0x39

# Register addresses
TSL2561_REG_CONTROL = 0x00
TSL2561_REG_TIMING = 0x01
TSL2561_REG_DATA0 = 0x0C
TSL2561_REG_DATA1 = 0x0E

# Control register values
TSL2561_CONTROL_POWERON = 0x03
TSL2561_CONTROL_POWEROFF = 0x00
TSL2561_CONTROL_RESET = 0x06

# Timing register values
TSL2561_TIMING_INTEGRATIONTIME_13MS = 0x00
TSL2561_TIMING_INTEGRATIONTIME_101MS = 0x01
TSL2561_TIMING_INTEGRATIONTIME_402MS = 0x02
TSL2561_TIMING_INTEGRATIONTIME_MASK = 0x03

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _write_register(bus, addr, reg, value):
    bus.write_byte_data(addr, reg, value)

def _read_register(bus, addr, reg):
    return bus.read_byte_data(addr, reg)

def _read_word(bus, addr, reg):
    data = bus.read_i2c_block_data(addr, reg, 2)
    return (data[1] << 8) | data[0]

def _read_lux(bus, addr):
    """Read raw channel values and compute lux. Returns (ch0, ch1, lux)."""
    ch0 = _read_word(bus, addr, TSL2561_REG_DATA0)
    ch1 = _read_word(bus, addr, TSL2561_REG_DATA1)

    if ch0 == 0xFFFF or ch1 == 0xFFFF:
        raise IOError("TSL2561 returned invalid data (0xFFFF)")

    atime = _read_register(bus, addr, TSL2561_REG_TIMING) & TSL2561_TIMING_INTEGRATIONTIME_MASK
    if atime == TSL2561_TIMING_INTEGRATIONTIME_13MS:
        ms = 14
    elif atime == TSL2561_TIMING_INTEGRATIONTIME_101MS:
        ms = 102
    elif atime == TSL2561_TIMING_INTEGRATIONTIME_402MS:
        ms = 404
    else:
        ms = 14

    if ch0 == 0:
        lux = 0.0
    else:
        ratio = ch1 / ch0
        if 0 < ratio <= 0.52:
            lux = (0.0315 * ch0) - (0.0593 * ch0 * (ratio ** 1.4))
        elif ratio <= 0.65:
            lux = (0.0229 * ch0) - (0.0291 * ch1)
        elif ratio <= 0.80:
            lux = (0.0157 * ch0) - (0.0180 * ch1)
        elif ratio <= 1.3:
            lux = (0.00338 * ch0) - (0.00260 * ch1)
        else:
            lux = 0.0

    lux = lux * (ms / 1000.0)
    return ch0, ch1, lux

def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = None
    try:
        bus = smbus2.SMBus(1)

        # Power on
        _write_register(bus, TSL2561_ADDR, TSL2561_REG_CONTROL, TSL2561_CONTROL_POWERON)
        time.sleep(0.05)

        # Set integration time to 101 ms
        _write_register(bus, TSL2561_ADDR, TSL2561_REG_TIMING, TSL2561_TIMING_INTEGRATIONTIME_101MS)
        time.sleep(0.01)

        while _running:
            try:
                ch0, ch1, lux = _read_lux(bus, TSL2561_ADDR)
                print(f"TSL2561 Lux: {lux:.2f}")
            except IOError as e:
                print(f"Error reading TSL2561: {e}", file=sys.stderr)

            # Sleep in small increments to allow prompt signal handling
            for _ in range(10):
                if not _running:
                    break
                time.sleep(0.1)

    except Exception as e:
        print(f"Fatal error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if bus is not None:
            try:
                _write_register(bus, TSL2561_ADDR, TSL2561_REG_CONTROL, TSL2561_CONTROL_POWEROFF)
            except Exception:
                pass
            bus.close()

if __name__ == "__main__":
    main()

