import signal
import sys
import time

from luma.core.interface.serial import i2c
from luma.core.render import canvas
from luma.oled.device import ssd1306

# --- Configuration -----------------------------------------------------------
I2C_BUS = 1
I2C_ADDR = 0x3C  # SSD1306 default I2C address (0x3C / 0x3D)
UPDATE_INTERVAL_S = 1.0

# --- Globals for cleanup -----------------------------------------------------
_device = None
_running = True


def _cleanup():
    """Release the OLED display and I2C bus."""
    global _device
    if _device is not None:
        try:
            _device.cleanup()
        except Exception:
            pass
        _device = None


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _validate_reading(value):
    """Return True if *value* is a numeric string or numeric value."""
    if isinstance(value, (int, float)):
        return True
    if isinstance(value, str):
        try:
            float(value)
            return True
        except ValueError:
            return False
    return False


def _display_reading(device, value):
    """Render *value* on the OLED; return True on success."""
    if not _validate_reading(value):
        print(f"[ERROR] Invalid reading: {value!r}", file=sys.stderr)
        return False
    try:
        with canvas(device) as draw:
            draw.text((0, 0), str(value), fill="white")
        return True
    except Exception as exc:
        print(f"[ERROR] Failed to update display: {exc}", file=sys.stderr)
        return False


def main():
    global _device

    # --- Signal handlers -----------------------------------------------------
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # --- Initialize I2C bus --------------------------------------------------
    try:
        serial = i2c(port=I2C_BUS, address=I2C_ADDR)
    except Exception as exc:
        print(
            f"[ERROR] Cannot open I2C bus {I2C_BUS} "
            f"at address 0x{I2C_ADDR:02X}: {exc}",
            file=sys.stderr,
        )
        sys.exit(1)

    # --- Initialize OLED device ---------------------------------------------
    try:
        _device = ssd1306(serial)
    except Exception as exc:
        print(
            f"[ERROR] SSD1306 not detected at 0x{I2C_ADDR:02X} on bus {I2C_BUS}: {exc}",
            file=sys.stderr,
        )
        _cleanup()
        sys.exit(1)

    # --- Main loop -----------------------------------------------------------
    try:
        while _running:
            if _display_reading(_device, "Hello"):
                time.sleep(UPDATE_INTERVAL_S)
            else:
                # Brief pause before retrying on invalid reading
                time.sleep(0.5)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

