            except DeviceClosed:
                print("Device closed unexpectedly.", file=sys.stderr)
                break

            print(f"GPIO {PIN_OUTPUT_1} and GPIO {PIN_OUTPUT_2} set to LOW")

            time.sleep(0.2)

    finally:
        try:
            output1.close()
        except Exception:
