import time
import signal
import sys
import board
import adafruit_dht

# BCM GPIO pins that the DHT22 data line is connected to
DHT_PINS = [board.D4, board.D17, board.D18, board.D22, board.D23, board.D27]

# Graceful shutdown flag
_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_dht22(sensor):
    """Read temperature and humidity from a DHT22 sensor.

    Returns (temperature_c, humidity) or (None, None) on failure.
    """
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is None or humidity is None:
            return None, None
        return temperature, humidity
    except RuntimeError as e:
        # DHT22 checksum or timing errors are common; log and continue
        print(f"DHT22 read error: {e}", file=sys.stderr)
        return None, None
    except Exception as e:
        print(f"Unexpected DHT22 error: {e}", file=sys.stderr)
        return None, None

def main():
    global _running

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensors = []
    try:
        for pin in DHT_PINS:
            try:
                sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
                sensors.append(sensor)
            except Exception as e:
                print(f"Failed to init DHT22 on pin {pin}: {e}", file=sys.stderr)
                sensors.append(None)

        cycle = 0
        while _running and cycle < 3:
            cycle += 1
            print(f"--- Cycle {cycle}/3 ---")

            for idx, sensor in enumerate(sensors):
                if sensor is None:
                    print(f"  GPIO {idx + 1}: N/A (sensor init failed)")
                    continue

                temperature, humidity = read_dht22(sensor)
                if temperature is not None and humidity is not None:
                    print(f"  GPIO {idx + 1}: {temperature:.1f}°C  {humidity:.1f}%")
                else:
                    print(f"  GPIO {idx + 1}: Read failed")

            # Sleep in small increments so signals are caught promptly
            slept = 0
            while _running and slept < 5:
                time.sleep(0.5)
                slept += 0.5

        if not _running:
            print("\nShutdown requested.", file=sys.stderr)

    finally:
        for sensor in sensors:
            if sensor is not None:
                try:
                    sensor.exit()
                except Exception:
                    pass
        print("DHT22 resources released.")

if __name__ == "__main__":
    main()

