import serial
import time
import sys

PORT = '/dev/serial0'
BAUD = 9600
TIMEOUT_S = 1.0
LOOP_INTERVAL_S = 0.5


def read_validated(ser: serial.Serial) -> str | None:
    """Read one line from the serial port and validate it.

    Returns the stripped line on success, or None if the read times out,
    the device sends an empty line, or the line is invalid.
    """
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None

    if not raw:
        # Timed out with no data
        return None

    line = raw.decode('ascii', errors='replace').strip()
    if not line:
        return None

    # Basic ASCII-only sanity check
    for ch in line:
        if ch not in ('\n', '\r') and (ch < ' ' or ch > '~'):
            return None

    return line


def main() -> int:
    ser = None
    try:
        ser = serial.Serial(PORT, BAUD, timeout=TIMEOUT_S)
        print(f"Opened {PORT} @ {BAUD} baud (timeout {TIMEOUT_S}s)")

        while True:
            reading = read_validated(ser)
            if reading is not None:
                print(f"Received: {reading}")
            time.sleep(LOOP_INTERVAL_S)

    except serial.SerialException as exc:
        print(f"Serial port error: {exc}", file=sys.stderr)
        return 1
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
        return 0
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")


if __name__ == "__main__":
    sys.exit(main())

