        # Apply HIGH state to each pin and report
        for dev in outputs:
            dev.on()
            print(f"GPIO {dev.pin.number} set to HIGH")

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
    finally:
        cleanup()

