            if not raw:
                # Timed out with no data; device may be absent or silent.
                print("No data received (timeout).", file=sys.stderr)
                return 0

            try:
                data = raw.decode('ascii', errors='replace').strip()
            except Exception as exc:
                print(f"Decode error: {exc}", file=sys.stderr)
                continue

            if not validate(data):
                print(f"Invalid data: {data!r}", file=sys.stderr)
                continue

            print(f"Received: {data}")
            time.sleep(LOOP_DELAY)

    except serial.SerialException as exc:
        print(f"Failed to open {PORT}: {exc}", file=sys.stderr)
        return 1
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
        return 0
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")


if __name__ == "__main__":
    sys.exit(main())

