import time

import smbus2

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
ACCEL_XOUT_H = 0x3B

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_raw_data(bus, addr):
    data = bus.read_i2c_block_data(addr, ACCEL_XOUT_H, 6)
    return (data[0] << 8) | data[1], (data[2] << 8) | data[3], (data[4] << 8) | data[5]


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = smbus2.SMBus(1)
    except OSError as exc:
        print(f"Error: cannot open I2C bus 1: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            bus.read_byte_data(MPU6050_ADDR, PWR_MGMT_1)
        except OSError:
            print(f"Error: no MPU6050 found at address 0x{MPU6050_ADDR:02X}", file=sys.stderr)
            sys.exit(1)

        for i in range(5):
            if not _running:
                break
            try:
                x, y, z = read_raw_data(bus, MPU6050_ADDR)
            except OSError as exc:
                print(f"Error reading MPU6050: {exc}", file=sys.stderr)
                sys.exit(1)
            print(f"Reading {i + 1}/5: x={x}, y={y}, z={z}")
            if i < 4 and _running:
                time.sleep(0.1)

    finally:
        if bus is not None:
            bus.close()


