import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

# BCM pin assignments
PINS = [5, 6, 12]
CYCLES = 3

devices = []

def cleanup(signum=None, frame=None):
    """Release all GPIO resources cleanly."""
    for dev in devices:
        try:
            dev.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def main():
    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        for pin in PINS:
            dev = OutputDevice(pin)
            devices.append(dev)

        for cycle in range(1, CYCLES + 1):
            for dev in devices:
                try:
                    # Apply the next logical state
                    dev.on()
                    state = "on" if dev.is_active else "off"
                    print(f"Cycle {cycle}/{CYCLES}: GPIO {dev.pin.number} -> {state}")
                except GPIOZeroError as e:
                    print(f"Cycle {cycle}/{CYCLES}: GPIO {dev.pin.number} -> ERROR: {e}", file=sys.stderr)
                    cleanup()
                    return

    except GPIOZeroError as e:
        print(f"GPIO initialization error: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    cleanup()

if __name__ == "__main__":
    main()

