import smbus2

I2C_BUS = 1
PCF8574_ADDR = 0x20
READ_INTERVAL = 0.1

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_pcf8574(bus, addr):
    """Read a byte from the PCF8574 and validate it is within [0, 255]."""
    raw = bus.read_byte(addr)
    if not isinstance(raw, int) or not (0 <= raw <= 0xFF):
        raise IOError(f"Invalid byte value: {raw!r}")
    return raw


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = smbus2.SMBus(I2C_BUS)
    except FileNotFoundError:
        print(f"Error: I2C bus {I2C_BUS} not found. Enable I2C with 'sudo raspi-config'.", file=sys.stderr)
        sys.exit(1)
    except PermissionError:
        print("Error: Permission denied on I2C bus. Run as root or add user to 'i2c' group.", file=sys.stderr)
        sys.exit(1)
    except OSError as exc:
        print(f"Error: Failed to open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                value = read_pcf8574(bus, PCF8574_ADDR)
            except OSError as exc:
                print(f"Error: No device at 0x{PCF8574_ADDR:02X}: {exc}", file=sys.stderr)
                sys.exit(1)
            except IOError as exc:
                print(f"Error: Invalid data from device: {exc}", file=sys.stderr)
                sys.exit(1)

            print(f"PCF8574 value: 0x{value:02X}")
            time.sleep(READ_INTERVAL)
    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass


