    from picamera2 import Picamera2
except ImportError:
    print("Error: picamera2 library is not installed. Install with: pip install picamera2", file=sys.stderr)
    sys.exit(1)

IMAGE_PATH = "image.jpg"
CAPTURE_INTERVAL = 0.5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def capture_image():
    """Captures an image using picamera2 and saves it to IMAGE_PATH."""
    picam2 = None
    try:
        picam2 = Picamera2()
        still_config = picam2.create_still_configuration()
        picam2.configure(still_config)
        picam2.start()
        picam2.capture_file(IMAGE_PATH)
        print(f"Image captured and saved to {IMAGE_PATH}")
    except Exception as e:
        print(f"Error capturing image: {e}", file=sys.stderr)
        return False
    finally:
        if picam2 is not None:
            try:
                picam2.stop()
            except Exception:
                pass
            try:
                picam2.close()
            except Exception:
                pass
    return True

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    if not os.path.exists("/dev/vchiq"):
        print("Error: Raspberry Pi camera device not found. Ensure the camera is enabled and connected.", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            if not capture_image():
                sys.exit(1)
            time.sleep(CAPTURE_INTERVAL)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

