import signal
import sys
import time

from gpiozero import DistanceSensor

# HC-SR04 ultrasonic distance sensor on a Raspberry Pi
# BCM numbering: echo=19, trigger=20, servo=24, LED=25, button=26
ECHO_PIN = 19
TRIGGER_PIN = 20

SENSOR = None
_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global SENSOR

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        SENSOR = DistanceSensor(
            echo=ECHO_PIN,
            trigger=TRIGGER_PIN,
            max_distance=4.0,   # HC-SR04 practical range ~4 m
        )
    except Exception as exc:
        print(f"Failed to initialize HC-SR04: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                distance_m = SENSOR.distance
            except Exception as exc:
                print(f"Sensor read error: {exc}", file=sys.stderr)
                time.sleep(1)
                continue

            if distance_m is None:
                print("Sensor: no reading (timeout or not ready)")
            else:
                print(f"Distance: {distance_m:.3f} m")

            time.sleep(1)
    finally:
        if SENSOR is not None:
            SENSOR.close()
        print("GPIO cleanup done.")


if __name__ == "__main__":
    main()

import signal
import sys
import time

import smbus2

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
ACCEL_XOUT_H = 0x3B

running = True


def _handle_signal(signum, frame):
    global running
    running = False


def read_raw_data(bus, addr):
    try:
        data = bus.read_i2c_block_data(addr, ACCEL_XOUT_H, 6)
    except OSError as exc:
        raise RuntimeError(f"I2C read failed at 0x{addr:02X}: {exc}") from exc
    if len(data) < 6:
        raise RuntimeError(f"short read: got {len(data)} bytes, expected 6")
    val = (data[0] << 8) | data[1]
    if val >= 0x8000:
        val -= 0x10000
    return val


def main():
    global running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = smbus2.SMBus(1)
    except OSError as exc:
        print(f"Cannot open I2C bus 1: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            bus.read_byte_data(MPU6050_ADDR, PWR_MGMT_1)
        except OSError:
            print(f"No MPU6050 found at 0x{MPU6050_ADDR:02X}", file=sys.stderr)
            sys.exit(1)
    except OSError as exc:
        print(f"I2C probe failed: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(8):
            if not running:
                break
            try:
                val = read_raw_data(bus, MPU6050_ADDR)
            except RuntimeError as exc:
                print(f"read error {i + 1}: {exc}", file=sys.stderr)
                continue
            print(f"Reading {i + 1}/8: {val}")
            time.sleep(0.1)
    finally:
        bus.close()


if __name__ == "__main__":
    main()

