import sys
import signal

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

OUTPUT_PIN = 18

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    output = None
    try:
        output = OutputDevice(OUTPUT_PIN)
        output.on()
        print(f"GPIO {OUTPUT_PIN} set HIGH", flush=True)
    except GPIOZeroError as exc:
        print(f"Error: failed to initialize GPIO {OUTPUT_PIN}: {exc}", file=sys.stderr, flush=True)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error initializing GPIO {OUTPUT_PIN}: {exc}", file=sys.stderr, flush=True)
        sys.exit(1)

    try:
        while _running:
            try:
                if not output.is_active:
                    print("GPIO state is not valid (inactive).", file=sys.stderr, flush=True)
                    sys.exit(1)
            except DeviceClosed:
                print("GPIO device was closed unexpectedly.", file=sys.stderr, flush=True)
                sys.exit(1)
            except Exception as exc:
                print(f"Error reading GPIO {OUTPUT_PIN}: {exc}", file=sys.stderr, flush=True)
                sys.exit(1)
    finally:
        if output is not None:
            try:
                output.close()
            except Exception:
                pass

if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PWM_PINS = [5, 6, 13, 17, 18, 22, 23, 24, 27]

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_pwm_value(pin: int) -> float:
    """Read the current PWM duty cycle (0.0–1.0) of a gpiozero PWMOutputDevice.

    Returns 0.0 if the device is closed or not ready.
    """
    try:
        dev = PWMOutputDevice(pin)
    except GPIOZeroError as exc:
        print(f"Error: cannot open GPIO {pin}: {exc}", file=sys.stderr)
        return 0.0
    except Exception as exc:
        print(f"Error: unexpected failure on GPIO {pin}: {exc}", file=sys.stderr)
        return 0.0

    try:
        value = dev.value
    except DeviceClosed:
        print(f"Warning: GPIO {pin} was closed before read.", file=sys.stderr)
        return 0.0
    except Exception as exc:
        print(f"Error: failed to read GPIO {pin}: {exc}", file=sys.stderr)
        return 0.0
    finally:
        try:
            dev.close()
        except Exception:
            pass

    if not 0.0 <= value <= 1.0:
        print(f"Warning: value {value} out of range on GPIO {pin}.", file=sys.stderr)
        return 0.0
    return value


def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    while _running:
        for pin in PWM_PINS:
            if not _running:
                break
            duty = read_pwm_value(pin)
            if duty == 0.0:
                continue
            print(f"GPIO {pin}: PWM duty cycle = {duty:.3f}")
        if _running:
            time.sleep(1)

    return 0


if __name__ == "__main__":
    sys.exit(main())

import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PIN_OUTPUT = 2
PIN_LED = 17

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        output = OutputDevice(PIN_OUTPUT)
        led = OutputDevice(PIN_LED)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO devices: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                output.on()
                led.on()
            except DeviceClosed:
                print("Device closed unexpectedly.", file=sys.stderr)
                break

            print(f"GPIO {PIN_OUTPUT} = ON, GPIO {PIN_LED} = ON")

            time.sleep(0.1)

            if not _running:
                break

            try:
                output.off()
                led.off()
            except DeviceClosed:
                print("Device closed unexpectedly.", file=sys.stderr)
                break

            print(f"GPIO {PIN_OUTPUT} = OFF, GPIO {PIN_LED} = OFF")
            time.sleep(0.1)

    except Exception as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)
        sys.exit(1)

    finally:
        try:
            output.close()
        except Exception:
            pass
        try:
            led.close()
        except Exception:
            pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

import serial
import sys
import time

PORT = '/dev/serial0'
BAUD = 9600
TIMEOUT_S = 1.0
LOOP_DELAY_S = 0.1


def main() -> int:
    ser = None
    try:
        ser = serial.Serial(PORT, BAUD, timeout=TIMEOUT_S)
        print(f"Opened {PORT} @ {BAUD} baud")

        while True:
            try:
                if ser.in_waiting > 0:
                    line = ser.readline()
                    if line:
                        print(line.decode('utf-8', errors='replace').strip())
            except serial.SerialException as exc:
                print(f"Serial read error: {exc}", file=sys.stderr)
                return 1

            time.sleep(LOOP_DELAY_S)

    except serial.SerialException as exc:
        print(f"Failed to open {PORT}: {exc}", file=sys.stderr)
        return 1
    except KeyboardInterrupt:
        print("\nInterrupted by user")
        return 0
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed")


if __name__ == "__main__":
    sys.exit(main())

