import serial
import sys
import time

PORT = '/dev/serial0'
BAUD = 9600
TIMEOUT_S = 2
READINGS = 3
INTER_READING_S = 2


def main() -> int:
    try:
        ser = serial.Serial(PORT, BAUD, timeout=TIMEOUT_S)
    except serial.SerialException as exc:
        print(f'Error: cannot open {PORT}: {exc}', file=sys.stderr)
        return 1

    try:
        for i in range(1, READINGS + 1):
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f'Error: serial read failed on reading {i}/{READINGS}: {exc}', file=sys.stderr)
                return 1

            if not raw:
                print(f'Warning: no data received on reading {i}/{READINGS} (device may be absent or busy).', file=sys.stderr)
                continue

            try:
                line = raw.decode('ascii', errors='replace').strip()
            except Exception as exc:
                print(f'Warning: decode error on reading {i}/{READINGS}: {exc}', file=sys.stderr)
                continue

            if line:
                print(f'Reading {i}/{READINGS}: {line}')

            if i < READINGS:
                time.sleep(INTER_READING_S)

    finally:
        try:
            ser.close()
        except Exception:
            pass

    return 0


if __name__ == '__main__':
    sys.exit(main())

import signal
import sys
import time

from gpiozero import PWMOutputDevice

PINS = [14, 15, 18]
INTERVAL = 0.1

devices = []


def cleanup(signum=None, frame=None):
    for dev in devices:
        try:
            dev.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main():
    for pin in PINS:
        try:
            dev = PWMOutputDevice(pin)
            devices.append(dev)
        except Exception as exc:
            print(f"Failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
            cleanup()
            sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        while True:
            for dev in devices:
                try:
                    duty = dev.value
                    print(f"GPIO {dev.pin.number}: duty cycle {duty:.2f}")
                except Exception as exc:
                    print(f"Error reading GPIO {dev.pin.number}: {exc}", file=sys.stderr)
            time.sleep(INTERVAL)
    except Exception as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

