import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

PWM_PIN = 18
VALID_MIN = 0.0
VALID_MAX = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_pwm_value(pwm: PWMOutputDevice) -> float | None:
    """Read the current PWM duty cycle, or None if the device is unavailable."""
    try:
        return float(pwm.value)
    except Exception:
        return None


def apply_pwm_value(pwm: PWMOutputDevice, value: float) -> bool:
    """Apply a PWM value, validating it first."""
    if not (VALID_MIN <= value <= VALID_MAX):
        print(f"Invalid PWM value: {value} (must be {VALID_MIN}–{VALID_MAX}).", file=sys.stderr)
        return False
    try:
        pwm.value = value
        print(f"PWM value applied: {value}")
        return True
    except GPIOZeroError as exc:
        print(f"GPIO error while setting PWM: {exc}", file=sys.stderr)
        return False
    except Exception as exc:
        print(f"Unexpected error while setting PWM: {exc}", file=sys.stderr)
        return False


def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        pwm = PWMOutputDevice(PWM_PIN)
    except GPIOZeroError as exc:
        print(f"Failed to initialize PWM on GPIO {PWM_PIN}: {exc}", file=sys.stderr)
        return 1
    except Exception as exc:
        print(f"Unexpected error initializing PWM on GPIO {PWM_PIN}: {exc}", file=sys.stderr)
        return 1

    try:
        current = read_pwm_value(pwm)
        if current is None:
            print("Failed to read PWM value from device.", file=sys.stderr)
            return 1

        if not apply_pwm_value(pwm, current):
            return 1

        # Brief pause so the user can observe the state change
        deadline = time.monotonic() + 1.0
        while _running and time.monotonic() < deadline:
            time.sleep(0.05)

        return 0
    finally:
        try:
            pwm.close()
        except Exception:
            pass


if __name__ == "__main__":
    sys.exit(main())

