import signal
import sys
import time
import board
import adafruit_dht

# --- Configuration -----------------------------------------------------------
DHT_PIN = board.D4          # BCM GPIO 4 (physical pin 7)
CYCLES = 3
DELAY_S = 2.0

# --- Globals for cleanup -----------------------------------------------------
_sensor = None
_running = True

def _cleanup():
    """Release the DHT22 hardware resource."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None

def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False

def main():
    global _sensor

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialise the DHT22 on GPIO 4
    try:
        _sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialise DHT22 on GPIO 4: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for cycle in range(1, CYCLES + 1):
            if not _running:
                break

            try:
                temperature = _sensor.temperature
                humidity = _sensor.humidity
            except RuntimeError as exc:
                # DHT22 checksum / timing errors are common; log and continue
                print(f"[cycle {cycle}/{CYCLES}] DHT22 read error: {exc}")
            except Exception as exc:
                print(f"[cycle {cycle}/{CYCLES}] Unexpected error reading DHT22: {exc}", file=sys.stderr)
            else:
                if temperature is not None and humidity is not None:
                    print(f"[cycle {cycle}/{CYCLES}] Temperature: {temperature:.1f} C  Humidity: {humidity:.1f} %")
                else:
                    print(f"[cycle {cycle}/{CYCLES}] DHT22 returned None (sensor absent?)")

            # DHT22 requires at least 2 s between reads; respect _running flag
            if cycle < CYCLES and _running:
                time.sleep(DELAY_S)

    finally:
        _cleanup()

if __name__ == "__main__":
    main()
